(33611, 'Ephesians 5:30', 'Ephesians', 5, 30, 'ځکه چې مونږ د هغه د بدن غړي یو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians5_verse_30.mp3', '', 1761754199, 1761754199),
(33612, 'Ephesians 5:31', 'Ephesians', 5, 31, 'لکه څنګه چې د خدای په کلام کې لیکل شوي دي: له همدې امله سړی خپل مور او پلار پرېږدي او د خپلې ښځې سره یوځای کیږي او دواړه یو بدن شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians5_verse_31.mp3', '', 1761754199, 1761754199),
(33613, 'Ephesians 5:32', 'Ephesians', 5, 32, 'دا یو لوی راز دی او زه د مسیح او کلیسا په هکله خبرې کوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians5_verse_32.mp3', '', 1761754199, 1761754199),
(33614, 'Ephesians 5:33', 'Ephesians', 5, 33, 'خو په هر حال، په تاسو کې دې هر مېړه باید د خپلې ښځې سره د خپل ځان په شان مینه وکړي او هره ښځه هم باید د خپل مېړه درناوی وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians5_verse_33.mp3', '', 1761754199, 1761754199),
(33615, 'Philippians 3:1', 'Philippians', 3, 1, 'اخر دا چې ای خویندو او ورونو! د څښتن سره په یووالي کې خوشحالي کوئ. دا زما دپاره کوم تکلیف نه دی چې تاسو ته هماغه شیان یوځل بیا لیکم او په دې کې ستاسو امن او سلامتي ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians3_verse_1.mp3', '', 1761754199, 1761754199),
(33616, 'Philippians 3:2', 'Philippians', 3, 2, 'د هغو خلکو سره چې د سپیانو په شان دي او د هغوی سره چې بدکاره دي، احتیاط کوئ چې په دې ټینګار کوي چې تاسو سنت کړي یعنې د خلاصون دپاره ستاسو د بدن یو غړی پرې کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians3_verse_2.mp3', '', 1761754199, 1761754199),
(33617, 'Philippians 3:3', 'Philippians', 3, 3, 'ځکه مونږ رښتیني سنت شوي خلک یو، مونږ چې د روح په وسیله د خدای عبادت کوو. مونږ په عیسی مسیح باندې ویاړ کوو او د جسماني مراسمو په سرته رسولو باور نه لرو،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians3_verse_3.mp3', '', 1761754199, 1761754199),
(33618, 'Philippians 3:4', 'Philippians', 3, 4, 'که څه هم زما سره دلیل شته چې په خپل ځان باندې تکیه وکړم. که چېرې نور خلک فکر کوي چې په جسماني مراسمو باندې تکیه کولای شي، نو زه د هغوی نه زیات کولای شم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians3_verse_4.mp3', '', 1761754199, 1761754199),
(33619, 'Philippians 3:5', 'Philippians', 3, 5, 'کله چې زه د اتو ورځو وم، سنت شوم. زه د اسراییلو د قوم او د بنیامین د قبیلې څخه یم او اصلي عبرانی یم او د شریعت د مراعت کولو په لحاظ فریسي وم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians3_verse_5.mp3', '', 1761754199, 1761754199),
(33620, 'Philippians 3:6', 'Philippians', 3, 6, 'زه دومره غیرتي وم چې د عیسی مسیح پیروان به مې ځورول او د شریعت د عادلانه معیارونو له مخې زه بې‌عیبه انسان وم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians3_verse_6.mp3', '', 1761754199, 1761754199),
(33621, 'Philippians 3:7', 'Philippians', 3, 7, 'خو هرڅه چې زما په ګټه وو، زه یې اوس د مسیح په تاوان ګڼم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians3_verse_7.mp3', '', 1761754199, 1761754199),
(33622, 'Philippians 3:8', 'Philippians', 3, 8, 'هو، یوازې دا نه، بلکې زما د څښتن عیسی مسیح پېژندل دومره قیمتي ؤ چې ما هرڅه د هغه په خاطر تاوان وګڼل. ما د هغه په خاطر هرڅه ایسته وغورځول او هغه ټول مې لکه د چټلیو په شان وګڼل، ترڅو مسیح خپل کړم', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians3_verse_8.mp3', '', 1761754199, 1761754199),
(33623, 'Philippians 3:9', 'Philippians', 3, 9, 'او د هغه سره یو شم. زه نور خپل ځان په شریعت باندې په عمل کولو سره عادل نه ګڼم، بلکې په مسیح باندې د ایمان په وسیله عادل شوی یم، هغه رښتینولي چې په ایمان باندې ولاړه ده او د خدای له خوا راځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians3_verse_9.mp3', '', 1761754199, 1761754199),
(33624, 'Philippians 3:10', 'Philippians', 3, 10, 'زه غواړم چې مسیح او د هغه د بیا راژوندي کېدلو قدرت وپېژنم، د هغه سره په کړاوونو کې شریک شم او د هغه په مرګ کې د هغه په شان شم،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians3_verse_10.mp3', '', 1761754199, 1761754199),
(33625, 'Philippians 3:11', 'Philippians', 3, 11, 'ترڅو د هرې لارې چې وي، زه هم د مړو نه بېرته د تل پاتې ژوند دپاره راژوندی شم. په هدف پسې هلې ځلې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians3_verse_11.mp3', '', 1761754199, 1761754199),
(33626, 'Philippians 3:12', 'Philippians', 3, 12, 'زه دا نه وایم چې ما دا هرڅه لا مخکې تر‌لاسه کړي دي او کامل شوی یم، بلکې د هغه د تر‌لاسه کولو دپاره هلې ځلې کوم، ځکه چې مسیح زه خپل کړی یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians3_verse_12.mp3', '', 1761754199, 1761754199),
(33627, 'Philippians 3:13', 'Philippians', 3, 13, 'ای خویندو او ورونو! زه فکر نه کوم چې هغه مې تر‌لاسه کړي دي. خو یو کار چې زه یې اوس کوم، هغه دا دی چې څه چې تېر شوي دي هغه هېر کړم او هغه څه چې مې مخکې دي د هغو دپاره ډېر کوښښ وکړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians3_verse_13.mp3', '', 1761754199, 1761754199),
(33628, 'Philippians 3:14', 'Philippians', 3, 14, 'زه د هدف پسې هلې ځلې کوم، ترڅو هغه جایزه تر‌لاسه کړم چې د هغې دپاره خدای زه د عیسی مسیح په وسیله اسماني ژوند ته بللی یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians3_verse_14.mp3', '', 1761754199, 1761754199),
(33629, 'Philippians 3:15', 'Philippians', 3, 15, 'مونږ ټول چې په روحاني توګه بالغان یو، باید همداسې فکر ولرو، او که په تاسو کې څوک بل ډول فکر لري، نو خدای به هغه تاسو ته ښکاره کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians3_verse_15.mp3', '', 1761754199, 1761754199),
(33630, 'Philippians 3:16', 'Philippians', 3, 16, 'په هر حال، راځئ چې د هغه معیار له مخې په مخ لاړ شو چې مونږ ورته رسېدلي یو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians3_verse_16.mp3', '', 1761754199, 1761754199),
(33631, 'Philippians 3:17', 'Philippians', 3, 17, 'ای خویندو او ورونو! زما د مثال نه پیروي وکړئ او هغو خلکو ته خپل پام راوګرځوئ چې زمونږ په شان ژوند تېروي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians3_verse_17.mp3', '', 1761754199, 1761754199),
(33632, 'Philippians 3:18', 'Philippians', 3, 18, 'ځکه ما څو څو ځلې تاسو ته ویلي دي او یوځل بیا یې درته د خپلو سترګو په اوښکو سره وایم چې ډېر خلک داسې ژوند کوي چې د عیسی مسیح د صلیب د رښتینې معنی سره دښمني لري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians3_verse_18.mp3', '', 1761754199, 1761754199),
(33633, 'Philippians 3:19', 'Philippians', 3, 19, 'د هغوی پای تباهي ده او د هغوی خدای د هغوی جسماني غوښتنې دي او هغوی په خپلو د شرم نه ډکو کارونو باندې ویاړ کوي. هغوی یوازې د دنیاوي شیانو په فکر کې دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians3_verse_19.mp3', '', 1761754199, 1761754199),
(33634, 'Philippians 3:20', 'Philippians', 3, 20, 'خو مونږ په اصل کې د اسمان اوسېدونکي یو او د خپل خلاصوونکي څښتن عیسی مسیح د راتللو په انتظار یو چې د اسمان نه به راځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians3_verse_20.mp3', '', 1761754199, 1761754199),
(33635, 'Philippians 3:21', 'Philippians', 3, 21, 'هغه به زمونږ کمزوری بدن داسې بدل کړي چې د هغه د جلال نه ډک بدن په شان شي. دا کار به د هغه قدرت په وسیله تر‌سره کیږي چې ټول شیان د خپل ځان تابع کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philippians3_verse_21.mp3', '', 1761754199, 1761754199),
(33636, 'Matthew 2:1', 'Matthew', 2, 1, 'کله چې عیسی د هیرودیس د پاچاهۍ په وخت کې د یهودیې د ولایت د بیت‌لحم په ښار کې وزېږېده، څه موده وروسته د ختیځ څخه ځینې ستوري پېژندونکي اورشلیم ته راغلل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew2_verse_1.mp3', '', 1761754199, 1761754199),
(33637, 'Matthew 2:2', 'Matthew', 2, 2, 'او پوښتنه یې کوله: «هغه نوی پیدا شوی ماشوم چې د یهودیانو پاچا کیږي چېرته دی؟ مونږ د هغه ستوری چې د لمرخاته له خوا راختلو، لیدلی دی او راغلي یو چې سجده ورته وکړو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew2_verse_2.mp3', '', 1761754199, 1761754199),
(33638, 'Matthew 2:3', 'Matthew', 2, 3, 'کله چې هیرودیس پاچا دا خبره واورېدله، نو ډېر پرېشانه شو او د اورشلیم ټول خلک هم پرېشانه شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew2_verse_3.mp3', '', 1761754199, 1761754199),
(33639, 'Matthew 2:4', 'Matthew', 2, 4, 'هغه ټول مشران کاهنان او د شریعت عالمان راوغوښتل او پوښتنه یې ترې وکړه چې مسیح به په کوم ځای کې وزېږي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew2_verse_4.mp3', '', 1761754199, 1761754199),
(33640, 'Matthew 2:5', 'Matthew', 2, 5, 'هغوی وویل: «د یهودیې په بیت‌لحم کې، ځکه چې یو پیغمبر داسې لیکلي دي:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew2_verse_5.mp3', '', 1761754199, 1761754199),
(33641, 'Matthew 2:6', 'Matthew', 2, 6, 'ای بیت‌لحمه چې د یهودیې په وطن کې یې! ته د یهودیې د لویو ښارونو څخه هېڅ کم نه یې، ځکه چې په تا کې به یو لارښوونکی پیدا کیږي چې د شپون په شان به زما د قوم اسراییلو لارښوونه کوي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew2_verse_6.mp3', '', 1761754199, 1761754199),
(33642, 'Matthew 2:7', 'Matthew', 2, 7, 'نو هیرودیس هغه ستوري پېژندونکي په پټه راوغوښتل او د هغوی څخه یې د ستوري د راختلو د ټاکلي وخت په هکله معلومات تر‌لاسه کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew2_verse_7.mp3', '', 1761754199, 1761754199),
(33643, 'Matthew 2:8', 'Matthew', 2, 8, 'بیا یې هغوی بیت‌لحم ته ولېږل او ورته ویې ویل: «لاړ شئ او په ډېر غور سره هغه ماشوم ولټوئ او کله چې مو پیدا کړ، نو ما خبر کړئ چې زه هم راشم او سجده ورته وکړم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew2_verse_8.mp3', '', 1761754199, 1761754199),
(33644, 'Matthew 2:9', 'Matthew', 2, 9, 'کله چې هغوی د پاچا خبرې واورېدلې، نو په خپله لاره روان شول او هماغه ستوری چې د لمرخاته خواته یې لیدلی ؤ، ولیده چې د هغوی څخه مخکې روان ؤ او په هغه ځای باندې ودرېده چېرته چې ماشوم ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew2_verse_9.mp3', '', 1761754199, 1761754199),
(33645, 'Matthew 2:10', 'Matthew', 2, 10, 'کله چې هغوی هغه ستوری ولیده، نو ډېر زیات خوشحاله شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew2_verse_10.mp3', '', 1761754199, 1761754199),
(33646, 'Matthew 2:11', 'Matthew', 2, 11, 'کله چې هغوی هغه کور ته ورننوتل او هغه ماشوم یې د خپلې مور مریم سره ولیده، نو ورته په سجده پرېوتل او د هغه عبادت یې وکړ. بیا یې د خپلو کڅوړو څخه سره زر، قیمتي خوشبویۍ او د مر کنډ راوویستل او د سوغات په توګه یې هغه ته ورکړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew2_verse_11.mp3', '', 1761754199, 1761754199),
(33647, 'Matthew 2:12', 'Matthew', 2, 12, 'څرنګه چې خدای هغوی ته په خوب کې خبرداری ورکړی ؤ چې بېرته هیرودیس ته لاړ نه شي، نو په بله لار خپل وطن ته ستانه شول. مصر ته تښتېدل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew2_verse_12.mp3', '', 1761754199, 1761754199),
(33648, 'Matthew 2:13', 'Matthew', 2, 13, 'کله چې هغوی لاړل، نو یوسف ته په خوب کې د څښتن یوه فرښته ښکاره شوه او ورته ویې ویل: «پاڅېږه، ماشوم او مور یې د ځان سره واخله او مصر ته وتښته او تر هغې پورې هلته پاتې شه، ترڅو زه درته ووایم چې راستون شه، ځکه چې هیرودیس به هغه ماشوم لټوي چې ویې وژني.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew2_verse_13.mp3', '', 1761754199, 1761754199),
(33649, 'Matthew 2:14', 'Matthew', 2, 14, 'نو یوسف پاڅېد او په هماغه شپه یې ماشوم او د هغه مور د ځان سره واخیستل او مصر ته لاړل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew2_verse_14.mp3', '', 1761754199, 1761754199),
(33650, 'Matthew 2:15', 'Matthew', 2, 15, 'او د هیرودیس تر مرګه پورې هلته پاتې شول. نو په دې ډول د څښتن هغه وینا چې د پیغمبر په وسیله یې کړې وه رښتیا شوه: خپل زوی مې د مصر څخه راوغوښت. د ماشومانو قتلول', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew2_verse_15.mp3', '', 1761754199, 1761754199),
(33651, 'Matthew 2:16', 'Matthew', 2, 16, 'کله چې هیرودیس پوه شو چې ستورو پېژندونکو هغه تېرایستلی دی، نو سخت په قهر شو او حکم یې وکړ چې د بیت‌لحم او د هغه شاوخوا سیمو ټول هلکان چې د دوه کالو او یا د هغې څخه کم عمر ولري، ووژني. او دا کار یې د هغو ستورو پېژندونکو د معلوماتو له مخې چې هغه ستوری به کله ښکاره کیږي، وکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew2_verse_16.mp3', '', 1761754199, 1761754199),
(33652, 'Matthew 2:17', 'Matthew', 2, 17, 'نو په دې ډول کومې خبرې چې خدای د خپل پیغمبر ارمیا په وسیله کړې وې هغه رښتیا شوې:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew2_verse_17.mp3', '', 1761754199, 1761754199),
(33653, 'Matthew 2:18', 'Matthew', 2, 18, 'په رامه کې یو اواز واورېدل شو، د ژړا او لوی ماتم اواز. راحیل په خپلو ماشومانو باندې ژاړي او تسلي نه مني، ځکه چې هغوی مړه شوي دي. د مصر څخه بېرته راستنېدل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew2_verse_18.mp3', '', 1761754199, 1761754199),
