(33695, 'Colossians 1:19', 'Colossians', 1, 19, 'ځکه چې دا د خدای خوښه وه چې زوی دې په خپل ځان کې د خدای کامل فطرت او خوی ولري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians1_verse_19.mp3', '', 1761754199, 1761754199),
(33696, 'Colossians 1:20', 'Colossians', 1, 20, 'خدای د مسیح په وسیله د ټولو شیانو سره پخلا شو او په صلیب باندې د مسیح د وینې د تویېدلو په وسیله یې د خدای او هغه څه چې په ځمکه او اسمان کې دي، ترمنځ سوله راوستله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians1_verse_20.mp3', '', 1761754199, 1761754199),
(33697, 'Colossians 1:21', 'Colossians', 1, 21, 'یو وخت تاسو د خدای نه لېرې وئ او د خپلو فکرونو او بدو عملونو له امله د هغه دښمنان وئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians1_verse_21.mp3', '', 1761754199, 1761754199),
(33698, 'Colossians 1:22', 'Colossians', 1, 22, 'خو اوس هغه د مسیح د جسماني مرګ په وسیله تاسو د خپل ځان سره پخلا کړئ، ترڅو تاسو سپېڅلي، بې‌عیبه او بې له ملامتۍ څخه خپل حضور ته راولي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians1_verse_22.mp3', '', 1761754199, 1761754199),
(33699, 'Colossians 1:23', 'Colossians', 1, 23, 'خو بې له شکه باید تاسو په ایمان کې قوي او ټینګ پاتې شئ او هغه هیله پرېنږدئ چې د زېري په اورېدلو سره په ټوله دنیا کې اعلان شوی دی او زه پولوس د همدې زېري خدمتګار شوم. د کلیسا د خدمتګار په توګه د پولوس کار', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians1_verse_23.mp3', '', 1761754199, 1761754199),
(33700, 'Colossians 1:24', 'Colossians', 1, 24, 'زه اوس په هغو کړاوونو کې خوشحاله یم چې ستاسو په خاطر یې تېروم، ځکه چې زه په خپل بدن کې د مسیح د بدن یعنې د کلیسا په خاطر د مسیح د تکلیفونو هغه کمی پوره کوم چې لا تر‌اوسه پاتې دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians1_verse_24.mp3', '', 1761754199, 1761754199),
(33701, 'Colossians 1:25', 'Colossians', 1, 25, 'زه د هغې وظیفې له مخې چې خدای ستاسو په خاطر ماته راکړې ده، د کلیسا خدمتګار شوم ترڅو د خدای کلام په پوره توګه تاسو ته درورسوم،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians1_verse_25.mp3', '', 1761754199, 1761754199),
(33702, 'Colossians 1:26', 'Colossians', 1, 26, 'یعنې هغه راز چې د پېړیو او تېرو نسلونو راهیسې پټ پاتې ؤ او اوس د خدای خلکو ته ښکاره شوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians1_verse_26.mp3', '', 1761754199, 1761754199),
(33703, 'Colossians 1:27', 'Colossians', 1, 27, 'خدای غوښتل چې تاسو غیریهودیانو ته د دې جلال نه ډکې شتمنۍ پټ راز ښکاره کړي او هغه راز دا دی چې مسیح په تاسو کې اوسیږي او هغه د جلال هیله ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians1_verse_27.mp3', '', 1761754199, 1761754199),
(33704, 'Colossians 1:28', 'Colossians', 1, 28, 'مونږ د مسیح په هکله ټولو ته وعظ کوو او په هغې ټولې پوهې سره چې مونږ یې لرو، ټولو ته خبرداری ورکوو او هر یو ته تعلیم ورکوو، ترڅو هر یو په روحاني لحاظ د بالغو خلکو په توګه په مسیح کې خدای ته وړاندې کړو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians1_verse_28.mp3', '', 1761754199, 1761754199),
(33705, 'Colossians 1:29', 'Colossians', 1, 29, 'د دې دپاره زه کار کوم او زحمت وباسم، ترڅو د هغه لوی قدرت نه کار واخلم چې مسیح یې ماته راکوي او په ما کې کار کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians1_verse_29.mp3', '', 1761754199, 1761754199),
(33706, 'Matthew 27:1', 'Matthew', 27, 1, 'کله چې سهار شو، نو ټولو مشرانو کاهنانو او د قوم مشرانو په خپل منځ کې مشوره وکړه چې عیسی څنګه ووژني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_1.mp3', '', 1761754199, 1761754199),
(33707, 'Matthew 27:2', 'Matthew', 27, 2, 'بیا یې هغه وتاړه او روان یې کړ او د روم والي پیلاتوس ته یې وسپاره. د یهودا ځان وژنه (د رسولانو عملونه ۱‏:‌۱۸‌‏-‌۱۹)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_2.mp3', '', 1761754199, 1761754199),
(33708, 'Matthew 27:3', 'Matthew', 27, 3, 'کله چې یهودا خاین پوه شو چې په عیسی باندې د مرګ حکم وشو، نو د خپل کار څخه پښېمانه شو او هغه د سپینو زرو دېرش سکې یې بېرته مشرانو کاهنانو او د قوم مشرانو ته راوړلې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_3.mp3', '', 1761754199, 1761754199),
(33709, 'Matthew 27:4', 'Matthew', 27, 4, 'او ویې ویل: «ما ګناه کړې ده چې د یو بې‌ګناه سړي سره مې خیانت وکړ او د هغه د مرګ سبب شوم.» خو هغوی وویل: «په مونږ یې څه؟ دا ستاسو کار دې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_4.mp3', '', 1761754199, 1761754199),
(33710, 'Matthew 27:5', 'Matthew', 27, 5, 'یهودا هغه سکې د خدای په کور کې په ځمکه وغورځولې او دباندې ووت او خپل ځان یې په دار وځړاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew27_verse_5.mp3', '', 1761754199, 1761754199);